CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Aliases" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Alias" text NOT NULL,
    "Canonical" text NOT NULL,
    CONSTRAINT "PK_Aliases" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoles" (
    "Id" text NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

CREATE TABLE "Exports" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "HouseholdId" uuid NOT NULL,
    "WeekId" integer NOT NULL,
    "Version" integer NOT NULL,
    "CreatedUtc" timestamp with time zone NOT NULL,
    "Snapshot" text NOT NULL,
    "ShoppingPdf" bytea NOT NULL,
    "MealsPdf" bytea NOT NULL,
    CONSTRAINT "PK_Exports" PRIMARY KEY ("Id")
);

CREATE TABLE "Households" (
    "Id" uuid NOT NULL,
    "Name" text NOT NULL,
    "Equipment" text NOT NULL,
    CONSTRAINT "PK_Households" PRIMARY KEY ("Id")
);

CREATE TABLE "Invitations" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "HouseholdId" uuid NOT NULL,
    "TokenHash" text NOT NULL,
    "ExpiresUtc" timestamp with time zone NOT NULL,
    "Used" boolean NOT NULL,
    "Revision" uuid NOT NULL,
    CONSTRAINT "PK_Invitations" PRIMARY KEY ("Id")
);

CREATE TABLE "Recipes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BookStackId" integer,
    "SourceHash" text NOT NULL,
    "Missing" boolean NOT NULL,
    "Title" text NOT NULL,
    "Description" text NOT NULL,
    "Steps" text NOT NULL,
    "Collection" text NOT NULL,
    "Category" text NOT NULL,
    "Tags" text NOT NULL,
    "Servings" numeric NOT NULL,
    "ActiveMinutes" integer,
    "CookMinutes" integer,
    "TotalMinutes" integer,
    "Kcal" integer,
    "KcalSource" text NOT NULL,
    "Allergens" text NOT NULL,
    "AllergensVerified" boolean NOT NULL,
    "Equipment" text NOT NULL,
    "FridgeHours" integer,
    "Freezable" boolean NOT NULL,
    "FreezerDays" integer,
    "Thaw" text NOT NULL,
    "Reheat" text NOT NULL,
    "Status" text NOT NULL,
    "Slug" text NOT NULL,
    "OldSlugs" text NOT NULL,
    "IngredientsJson" text NOT NULL,
    "Revision" uuid NOT NULL,
    CONSTRAINT "PK_Recipes" PRIMARY KEY ("Id")
);

CREATE TABLE "Reminders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "HouseholdId" uuid NOT NULL,
    "RuleId" integer NOT NULL,
    "Period" text NOT NULL,
    "Product" text NOT NULL,
    "Unit" text NOT NULL,
    "Quantity" numeric NOT NULL,
    "Decision" text NOT NULL,
    CONSTRAINT "PK_Reminders" PRIMARY KEY ("Id")
);

CREATE TABLE "Rules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "HouseholdId" uuid NOT NULL,
    "Product" text NOT NULL,
    "Unit" text NOT NULL,
    "Quantity" numeric NOT NULL,
    "EveryMonths" integer NOT NULL,
    "WinterQuantity" numeric,
    "AutumnQuantity" numeric,
    "ExceptionMonth" integer,
    "MonthQuantity" numeric,
    CONSTRAINT "PK_Rules" PRIMARY KEY ("Id")
);

CREATE TABLE "Settings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PublicCatalog" boolean NOT NULL,
    "PublicRegistration" boolean NOT NULL,
    CONSTRAINT "PK_Settings" PRIMARY KEY ("Id")
);

CREATE TABLE "Weeks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "HouseholdId" uuid NOT NULL,
    "Monday" date NOT NULL,
    "Revision" uuid NOT NULL,
    "DataJson" text NOT NULL,
    CONSTRAINT "PK_Weeks" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUsers" (
    "Id" text NOT NULL,
    "HouseholdId" uuid NOT NULL,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUsers_Households_HouseholdId" FOREIGN KEY ("HouseholdId") REFERENCES "Households" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "AspNetUserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserRoles" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_Aliases_Alias" ON "Aliases" ("Alias");

CREATE INDEX "IX_AspNetRoleClaims_RoleId" ON "AspNetRoleClaims" ("RoleId");

CREATE UNIQUE INDEX "RoleNameIndex" ON "AspNetRoles" ("NormalizedName");

CREATE INDEX "IX_AspNetUserClaims_UserId" ON "AspNetUserClaims" ("UserId");

CREATE INDEX "IX_AspNetUserLogins_UserId" ON "AspNetUserLogins" ("UserId");

CREATE INDEX "IX_AspNetUserRoles_RoleId" ON "AspNetUserRoles" ("RoleId");

CREATE INDEX "EmailIndex" ON "AspNetUsers" ("NormalizedEmail");

CREATE INDEX "IX_AspNetUsers_HouseholdId" ON "AspNetUsers" ("HouseholdId");

CREATE UNIQUE INDEX "UserNameIndex" ON "AspNetUsers" ("NormalizedUserName");

CREATE UNIQUE INDEX "IX_Exports_WeekId_Version" ON "Exports" ("WeekId", "Version");

CREATE UNIQUE INDEX "IX_Invitations_TokenHash" ON "Invitations" ("TokenHash");

CREATE UNIQUE INDEX "IX_Recipes_BookStackId" ON "Recipes" ("BookStackId");

CREATE UNIQUE INDEX "IX_Reminders_HouseholdId_RuleId_Period" ON "Reminders" ("HouseholdId", "RuleId", "Period");

CREATE UNIQUE INDEX "IX_Weeks_HouseholdId_Monday" ON "Weeks" ("HouseholdId", "Monday");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261118130739_Initial', '10.0.0');

COMMIT;

START TRANSACTION;
DROP INDEX "IX_AspNetUsers_HouseholdId";

ALTER TABLE "AspNetUsers" ADD "MemberSlot" integer NOT NULL DEFAULT 1;

WITH ranked AS (
    SELECT "Id", row_number() OVER (PARTITION BY "HouseholdId" ORDER BY "Id") AS slot
    FROM "AspNetUsers"
)
UPDATE "AspNetUsers" AS u SET "MemberSlot" = ranked.slot
FROM ranked WHERE u."Id" = ranked."Id";

CREATE UNIQUE INDEX "IX_AspNetUsers_HouseholdId_MemberSlot" ON "AspNetUsers" ("HouseholdId", "MemberSlot");

ALTER TABLE "AspNetUsers" ADD CONSTRAINT "CK_MemberSlot" CHECK ("MemberSlot" IN (1, 2));

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261118131723_HouseholdMemberSlots', '10.0.0');

COMMIT;

